import { loadRecord_cyber_telemetry_stream } from "../src/service.mjs";

const cases = [
  {
    input: {"profile":{"age":0}},
    code: "SCHEMA_EMAIL_MISSING",
    path: "profile.email",
  },
  {
    input: {"profile":{"email":"reader@example.test","age":-1}},
    code: "SCHEMA_AGE_RANGE",
    path: "profile.age",
  },
];

const errors = cases.map(({ input }) => {
  try {
    loadRecord_cyber_telemetry_stream(input);
    return null;
  } catch (error) {
    return error;
  }
});

const structured = errors.every((error, index) =>
  error?.code === cases[index].code && error?.path === cases[index].path
);
const presentationOnly = errors.every((error, index) =>
  error?.message.includes(cases[index].path) &&
  error?.cause?.code === cases[index].code
);
const valid = loadRecord_cyber_telemetry_stream({"profile":{"email":"reader@example.test","age":0}});

if (structured && valid["profile"]["age"] === 0) {
  console.log("FIXED: structured schema errors preserve code and field path");
  process.exit(0);
}
if (presentationOnly) {
  console.log("CHECK_FAILED: record loading does not preserve the required error contract");
  process.exit(2);
}

console.log("UNFIXED: schema failures lose their structured code or field path");
process.exit(1);

function validateRecord(record) {
  if (typeof record.profile?.email !== "string") {
    throw Object.assign(new Error("email is required"), {
      code: "SCHEMA_EMAIL_MISSING",
      path: "profile.email",
    });
  }
  if (!Number.isInteger(record.profile?.age) || record.profile.age < 0) {
    throw Object.assign(new Error("age is below its minimum"), {
      code: "SCHEMA_AGE_RANGE",
      path: "profile.age",
    });
  }
  return record;
}

export function loadRecord_cyber_telemetry_stream(record) {
  return validateRecord(record);
}

/**
 * Helper routines for cyber-telemetry-stream
 *
 * Provides header builders, service context factories, and validation guards.
 */
import { formatDomainName_cyber_telemetry_stream, generateTraceId_cyber_telemetry_stream } from "../utils.js";

export function getDomainHeader_cyber_telemetry_stream(domain: string): string {
  return "X-Domain-" + formatDomainName_cyber_telemetry_stream(domain);
}

export function createServiceContext_cyber_telemetry_stream(domain: string): { domain: string; traceId: string; timestamp: number } {
  return {
    domain: formatDomainName_cyber_telemetry_stream(domain),
    traceId: generateTraceId_cyber_telemetry_stream(),
    timestamp: Date.now(),
  };
}

export function validateDomainHeader_cyber_telemetry_stream(header: string): boolean {
  return typeof header === "string" && header.startsWith("X-Domain-");
}

export function buildResponseEnvelope_cyber_telemetry_stream<T>(
  data: T,
  status = "ok",
): { status: string; data: T; timestamp: string } {
  return { status, data, timestamp: new Date().toISOString() };
}
